 if(Object.keys(ward).some(key=>!['allowed','attempted','state','events','saves'].includes(key))||ward.attempted!==true||!requirements.some(entry=>entry.receipt?.success!==true))throw Error('mastermind-queued-form:actual-pending-Ward-required')
